// ===== Baralho e movimentos =====
let cardUid = 0;

function makeCard(suit, rank) {
    return { id: ++cardUid, suit, rank, faceUp: false };
}

function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}

function buildDeck(suits) {
    const perSuit = 8 / suits.length;
    const deck = [];
    for (const suit of suits) {
        for (let rep = 0; rep < perSuit; rep++) {
            for (let rank = 1; rank <= 13; rank++) deck.push(makeCard(suit, rank));
        }
    }
    return shuffle(deck);
}

function newGameBoard(suits) {
    const deck = buildDeck(suits);
    const columns = [];
    for (let i = 0; i < COLUMNS; i++) {
        const count = i < 4 ? 6 : 5;
        const pile = [];
        for (let j = 0; j < count; j++) {
            const card = deck.pop();
            card.faceUp = (j === count - 1);
            pile.push(card);
        }
        columns.push(pile);
    }
    return { columns, stock: deck };
}

function exposeTop(colIndex) {
    const col = state.columns[colIndex];
    const topCard = col[col.length - 1];
    if (topCard && !topCard.faceUp) topCard.faceUp = true;
}

function moveCard(from, idx, to) {
    if (!state.active || from === to) return false;
    const col = state.columns[from];
    if (!isPickupRun(from, idx)) return false;
    const moving = col.slice(idx);
    if (!canDrop(moving, to)) return false;
    pushUndo();
    col.splice(idx);
    exposeTop(from);
    state.columns[to].push(...moving);
    state.moves++;
    state.score = Math.max(0, state.score - MOVE_COST);
    playMove();
    clearHint();
    state.grabbed = null;
    afterMove(to);
    renderAll();
    renderScoreboard();
    updateFace();
    checkGame();
    return true;
}

function afterMove(colIndex) {
    if (!findCompletedRun(colIndex)) return;
    const col = state.columns[colIndex];
    const suit = col[col.length - 13].suit;
    col.splice(-13);
    exposeTop(colIndex);
    state.foundations.push({ suit });
    state.score += RUN_BONUS;
    playRun();
    talkFace();
    messageElGood(`Run de ${SUIT_INFO[suit].name} completa! +${RUN_BONUS} pontos.`);
}

function dealStock() {
    if (!state.active || state.stock.length === 0) return;
    if (state.columns.some(c => c.length === 0)) {
        messageElWarn('Preencha as colunas vazias antes de distribuir.');
        playError();
        return;
    }
    pushUndo();
    for (let i = 0; i < COLUMNS && state.stock.length > 0; i++) {
        const card = state.stock.pop();
        card.faceUp = true;
        state.columns[i].push(card);
    }
    state.moves++;
    state.score = Math.max(0, state.score - 10);
    playDeal();
    clearHint();
    state.grabbed = null;
    state.columns.forEach((c, i) => afterMove(i));
    renderAll();
    renderScoreboard();
    updateFace();
    checkGame();
}

