// ===== Regras =====
function isPickupRun(colIndex, idx) {
    const cards = state.columns[colIndex];
    if (idx < 0 || idx >= cards.length) return false;
    if (!cards[idx].faceUp) return false;
    for (let i = idx; i < cards.length - 1; i++) {
        const a = cards[i];
        const b = cards[i + 1];
        if (!b.faceUp || b.suit !== a.suit || b.rank !== a.rank - 1) return false;
    }
    return true;
}

function canDrop(run, targetCol) {
    if (targetCol < 0 || targetCol >= state.columns.length) return false;
    const target = state.columns[targetCol];
    if (target.length === 0) return true;
    const last = target[target.length - 1];
    return last.faceUp && last.rank === run[0].rank + 1;
}

function findCompletedRun(colIndex) {
    const cards = state.columns[colIndex];
    if (cards.length < 13) return false;
    const tail = cards.slice(-13);
    if (!tail.every(c => c.faceUp)) return false;
    const suit = tail[0].suit;
    for (let i = 0; i < 13; i++) {
        if (tail[i].suit !== suit || tail[i].rank !== 13 - i) return false;
    }
    return true;
}

function canDeal() {
    return state.stock.length > 0 && state.columns.every(c => c.length > 0);
}

function allMoves() {
    const moves = [];
    state.columns.forEach((col, from) => {
        col.forEach((card, idx) => {
            if (!isPickupRun(from, idx)) return;
            state.columns.forEach((target, to) => {
                if (to === from) return;
                if (canDrop(col.slice(idx), to)) moves.push({ from, idx, to });
            });
        });
    });
    return moves;
}

function moveQuality(m) {
    const cards = state.columns[m.from];
    const moving = cards.slice(m.idx);
    const below = m.idx > 0 ? cards[m.idx - 1] : null;
    const target = state.columns[m.to];
    const targetLast = target.length > 0 ? target[target.length - 1] : null;
    let q = 0;
    if (targetLast) {
        if (targetLast.suit === moving[0].suit) q += 4;
    } else {
        q -= 2;
        if (m.idx === 0) q += 4;
    }
    if (below && below.faceUp && below.suit === moving[0].suit) q += 1.5;
    if (moving.length === 1) q += 0.5;
    return q;
}

function bestMove() {
    const moves = allMoves();
    if (moves.length === 0) return null;
    let best = null;
    let bestQ = -Infinity;
    for (const m of moves) {
        const q = moveQuality(m) + Math.random() * 0.1;
        if (q > bestQ) {
            bestQ = q;
            best = m;
        }
    }
    return best;
}

function hasAnyMove() {
    return allMoves().length > 0 || canDeal();
}

