// ===== Dica =====
let hintTimeout = null;

function hintMove() {
    if (!state.active || state.hintUsed) return;
    state.hintUsed = true;
    hintBtn.disabled = true;
    const m = bestMove();
    if (!m) {
        hintText.textContent = 'Não há movimentos — desfaça ou comece um novo jogo.';
        talkFace();
        return;
    }
    state.hint = m;
    hintText.textContent = `Dica: mova a pilha da coluna ${m.from + 1} (posição ${m.idx + 1}) para a coluna ${m.to + 1}.`;
    talkFace();
    renderAll();
    clearTimeout(hintTimeout);
    hintTimeout = setTimeout(() => {
        state.hint = null;
        renderAll();
    }, 8000);
}

function clearHint() {
    state.hint = null;
    clearTimeout(hintTimeout);
}

