// ===== Desfazer =====
function snapshot() {
    return {
        columns: state.columns.map(col => col.map(c => ({ suit: c.suit, rank: c.rank, faceUp: c.faceUp }))),
        stock: state.stock.map(c => ({ suit: c.suit, rank: c.rank })),
        foundations: state.foundations.map(f => ({ suit: f.suit })),
        score: state.score,
        moves: state.moves
    };
}

function pushUndo() {
    state.undoStack.push(snapshot());
    if (state.undoStack.length > 80) state.undoStack.shift();
}

function undoMove() {
    if (state.result === 'win' || state.undoStack.length === 0) return;
    const s = state.undoStack.pop();
    state.columns = s.columns.map(col => col.map(c => ({ id: ++cardUid, suit: c.suit, rank: c.rank, faceUp: c.faceUp })));
    state.stock = s.stock.map(c => ({ id: ++cardUid, suit: c.suit, rank: c.rank, faceUp: false }));
    state.foundations = s.foundations.map(f => ({ suit: f.suit }));
    state.score = s.score;
    state.moves = s.moves;
    state.active = true;
    state.result = null;
    state.grabbed = null;
    clearHint();
    playMove();
    messageElSoft('Movimento desfeito.');
    renderAll();
    renderScoreboard();
    updateFace();
}

