// ===== Fim de jogo =====
function checkGame() {
    if (state.foundations.length >= TOTAL_RUNS) {
        winRound();
        return;
    }
    if (state.active && !hasAnyMove()) stuckRound();
}

function stuckRound() {
    state.result = 'stuck';
    messageElWarn('Sem movimentos! Desfaça (U) ou comece um novo jogo.');
    playError();
    updateFace();
    updateButtons();
}

function winRound() {
    state.active = false;
    state.result = 'win';
    state.hint = null;
    state.grabbed = null;
    stats.games++;
    stats.wins++;
    stats.streak++;
    if (stats.streak > stats.bestStreak) stats.bestStreak = stats.streak;
    saveValue('spider.stats', stats);
    refreshBest();
    if (state.score > bestScore) {
        bestScore = state.score;
        saveValue('spider.best.' + state.difficulty, bestScore);
    }
    playWin();
    messageElGood('Parabéns, Espadão! Todas as 8 runs completas!');
    triggerFireworks();
    updateFace();
    newGameBtn.textContent = 'Jogar de Novo';
    renderAll();
    renderScoreboard();
}

