    state.cursor = { col: 0, row: 0 };
    state.cursorActive = false;

    messageElement.textContent = '';
    messageElement.style.color = '';
    hintText.textContent = '';
    newGameBtn.textContent = 'Novo Jogo';
    resetFace();
    spiderCanvas.style.display = 'none';
    if (fireworkEngine) fireworkEngine.stop();
    renderAll();
    renderScoreboard();
    updateFace();
    playDeal();
}

