// ===== Inicialização =====
document.addEventListener('DOMContentLoaded', () => {
    if (typeof FireworkEngine === 'function') {
        fireworkEngine = new FireworkEngine();
        fireworkEngine.init('spiderCanvas');
    } else {
        console.warn('FireworkEngine indisponível: fogos de artifício desativados.');
    }

    setActiveBtns(document.getElementById('difficultyGroup'), state.difficulty, 'data-diff');
    applyTheme();
    applySoundToggle();

    // Dificuldade (reinicia o jogo, como no Windows)
    document.querySelectorAll('#difficultyGroup button').forEach(btn => {
        btn.addEventListener('click', () => {
            state.difficulty = btn.dataset.diff;
            try { localStorage.setItem('spider.difficulty', state.difficulty); } catch (e) { /* modo privado */ }
            setActiveBtns(document.getElementById('difficultyGroup'), state.difficulty, 'data-diff');
            refreshBest();
            initRound();
            renderScoreboard();
        });
    });

    // Som
    soundToggle.addEventListener('click', () => {
        state.soundOn = !state.soundOn;
        try { localStorage.setItem('spider.sound', state.soundOn ? 'on' : 'off'); } catch (e) { /* modo privado */ }
        applySoundToggle();
    });

    // Tema
    themeToggle.addEventListener('click', () => {
        state.theme = state.theme === 'dark' ? 'light' : 'dark';
        try { localStorage.setItem('spider.theme', state.theme); } catch (e) { /* modo privado */ }
        applyTheme();
    });

    // Ações do menu
    newGameBtn.addEventListener('click', () => initRound());
    dealBtn.addEventListener('click', dealStock);
    undoBtn.addEventListener('click', undoMove);
    hintBtn.addEventListener('click', hintMove);
    assistBtn.addEventListener('click', autoMove);
    stockElement.addEventListener('click', dealStock);

    attachDrag();

    // Teclado: setas movem, Espaço agarra/solta, D distribui, U desfaça, H dica, A auto-mover
    document.addEventListener('keydown', (event) => {
        if (event.ctrlKey || event.metaKey || event.altKey) return;
        const key = event.key;
        if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight') {
            if (!state.active) return;
            event.preventDefault();
            moveCursor(key);
            return;
        }
        if (key === ' ' || key === 'Enter') {
            if (state.active) {
                event.preventDefault();
                keyboardGrabDrop();
                return;
            }
            if (state.result !== 'win') newGameBtn.click();
            return;
        }
        if (key === 'Escape') {
            state.grabbed = null;
            renderAll();
            return;
        }
        const k = key.toLowerCase();
        if (k === 'd') dealStock();
        else if (k === 'u') undoMove();
        else if (k === 'h') hintMove();
        else if (k === 'a') autoMove();
    });

    function moveCursor(key) {
        const cur = state.cursor;
        state.cursorActive = true;
        if (key === 'ArrowLeft') cur.col = (cur.col + 9) % COLUMNS;
        else if (key === 'ArrowRight') cur.col = (cur.col + 1) % COLUMNS;
        else if (key === 'ArrowUp') cur.row = Math.max(0, cur.row - 1);
        else if (key === 'ArrowDown') cur.row += 1;
        cur.row = Math.min(cur.row, Math.max(0, state.columns[cur.col].length - 1));
        renderAll();
    }

    function keyboardGrabDrop() {
        state.cursorActive = true;
        const { col, row } = state.cursor;
        if (state.grabbed) {
            if (col === state.grabbed.col) {
                state.grabbed = null;
                renderAll();
                return;
            }
            const run = state.columns[state.grabbed.col].slice(state.grabbed.idx);
            if (canDrop(run, col)) {
                const from = state.grabbed.col;
                const idx = state.grabbed.idx;
                state.grabbed = null;
                moveCard(from, idx, col);
            } else {
                playError();
                messageElWarn('Coluna inválida para essa pilha.');
            }
            return;
        }
        if (isPickupRun(col, row)) {
            state.grabbed = { col, idx: row };
            messageElSoft('Pilha agarrada! Mova com as setas e pressione Espaço para soltar.');
            renderAll();
        } else {
            playError();
        }
    }

    renderScoreboard();
    startBlinking();
    startEyeFollowing();
    initRound();
});

