// ===== Placar (localStorage) =====
function loadValue(key, fallback) {
    try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
        return fallback;
    }
}

function saveValue(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (e) { /* modo privado */ }
}

const stats = loadValue('spider.stats', { games: 0, wins: 0, streak: 0, bestStreak: 0 });
let bestScore = loadValue('spider.best.' + state.difficulty, 0);

function refreshBest() {
    bestScore = loadValue('spider.best.' + state.difficulty, 0);
}

