// ===== Arrastar e soltar =====
let drag = null;

function attachDrag() {
    tableauElement.addEventListener('mousedown', onDragStart);
    document.addEventListener('mousemove', onDragMove);
    document.addEventListener('mouseup', onDragEnd);
}

function onDragStart(e) {
    if (!state.active || e.button !== 0) return;
    const cardEl = e.target.closest ? e.target.closest('.card') : null;
    if (!cardEl || !cardEl.classList.contains('face-up')) return;
    const col = Number(cardEl.dataset.col);
    const idx = Number(cardEl.dataset.idx);
    if (!isPickupRun(col, idx)) return;
    e.preventDefault();
    drag = { col, idx, startX: e.clientX, startY: e.clientY, moved: false, ghost: null };
}

function onDragMove(e) {
    if (!drag) return;
    if (!drag.moved) {
        if (Math.hypot(e.clientX - drag.startX, e.clientY - drag.startY) < 6) return;
        drag.moved = true;
        const topCard = state.columns[drag.col][drag.idx];
        const ghost = document.createElement('div');
        ghost.className = 'drag-ghost';
        ghost.innerHTML = cardSVG(topCard);
        document.body.appendChild(ghost);
        drag.ghost = ghost;
        state.columns[drag.col].forEach((c, i) => {
            if (i >= drag.idx) {
                const el = tableauElement.querySelector(`.col[data-col="${drag.col}"] .card[data-idx="${i}"]`);
                if (el) el.classList.add('dragging');
            }
        });
    }
    const ghost = drag.ghost;
    const rect = ghost.getBoundingClientRect();
    ghost.style.left = `${e.clientX - rect.width / 2}px`;
    ghost.style.top = `${e.clientY - rect.height / 2}px`;
    const target = columnAt(e.clientX, e.clientY);
    const run = state.columns[drag.col].slice(drag.idx);
    setDropTarget(target >= 0 && target !== drag.col && canDrop(run, target) ? target : -1);
}

function onDragEnd(e) {
    if (!drag) return;
    const d = drag;
    drag = null;
    if (d.moved) {
        if (d.ghost && d.ghost.parentNode) d.ghost.parentNode.removeChild(d.ghost);
        setDropTarget(-1);
        const target = columnAt(e.clientX, e.clientY);
        const run = state.columns[d.col].slice(d.idx);
        if (target >= 0 && target !== d.col && canDrop(run, target)) {
            moveCard(d.col, d.idx, target);
        } else {
            if (run.length === 1 && run[0].rank === 1) {
                messageElSoft('O As só vai para a pilha final quando a sequência K→A do mesmo naipe se completa — isso é automático.');
            }
            renderAll();
        }
    } else {
        clickMove(d.col, d.idx);
    }
}

function clickMove(col, idx) {
    if (!state.active) return;
    const run = state.columns[col].slice(idx);
    const targets = [];
    state.columns.forEach((t, to) => {
        if (to !== col && canDrop(run, to)) targets.push(to);
    });
    if (targets.length === 0) {
        playError();
        if (run.length === 1 && run[0].rank === 1) {
            messageElSoft('O As só vai para a pilha final quando a sequência K→A do mesmo naipe se completa — isso é automático.');
        } else {
            messageElSoft('Sem destino para essa pilha.');
        }
        return;
    }
    let best = targets[0];
    let bestQ = -Infinity;
    for (const to of targets) {
        const q = moveQuality({ from: col, idx, to }) + Math.random() * 0.1;
        if (q > bestQ) {
            bestQ = q;
            best = to;
        }
    }
    moveCard(col, idx, best);
}

function columnAt(x, y) {
    const cols = tableauElement.children;
    for (let i = 0; i < cols.length; i++) {
        const r = cols[i].getBoundingClientRect();
        if (x >= r.left - 4 && x <= r.right + 4 && y >= r.top - 30 && y <= r.bottom + 60) return i;
    }
    return -1;
}

function setDropTarget(colIndex) {
    const cols = tableauElement.children;
    for (let i = 0; i < cols.length; i++) {
        cols[i].classList.toggle('drop-target', i === colIndex);
    }
}

