6	function renderTableau() {
7	    tableauElement.innerHTML = '';
8	    state.columns.forEach((col, ci) => {
9	        const colEl = document.createElement('div');
10	        colEl.className = 'col' + (col.length === 0 ? ' empty' : '');
11	        colEl.dataset.col = String(ci);
12	        let top = 0;
13	        col.forEach((card, idx) => {
14	            const cardEl = document.createElement('div');
15	            cardEl.className = 'card ' + (card.faceUp ? 'face-up' : 'face-down');
16	            cardEl.dataset.col = String(ci);
17	            cardEl.dataset.idx = String(idx);
18	            cardEl.style.top = `calc(var(--card-h) * ${top.toFixed(3)})`;
19	            cardEl.innerHTML = card.faceUp ? cardSVG(card) : cardBackSVG();
20	            if (state.hint && state.hint.from === ci && state.hint.idx === idx) cardEl.classList.add('hint-src');
21	            if (state.grabbed && state.grabbed.col === ci && idx >= state.grabbed.idx) cardEl.classList.add('grabbed');
22	            if (state.cursorActive && state.cursor.col === ci && state.cursor.row === idx) cardEl.classList.add('cursor');
23	            colEl.appendChild(cardEl);
24	            top += cardStep(card);
25	        });
26	        colEl.style.height = `calc(var(--card-h) * ${(top + 1).toFixed(3)})`;
27	        if (state.hint && state.hint.to === ci) colEl.classList.add('hint-dst');
28	        tableauElement.appendChild(colEl);
29	    });
30	}
31	
