37	            slot.className = 'found-slot filled';
38	            slot.innerHTML = foundationSVG(state.foundations[i].suit);
39	        } else {
40	            slot.className = 'found-slot';
41	            slot.textContent = '?';
42	        }
43	        foundationsElement.appendChild(slot);
44	    }
45	}
