50	    if (deals > 0) {
51	        stockElement.className = 'stock';
52	        stockElement.title = 'Distribuir cartas (D)';
53	        for (let i = 0; i < 2; i++) {
54	            const back = document.createElement('div');
55	            back.className = 'stack-card';
56	            back.innerHTML = cardBackSVG();
57	            stockElement.appendChild(back);
58	        }
59	        const badge = document.createElement('span');
60	        badge.className = 'badge';
61	        badge.textContent = String(deals);
62	        stockElement.appendChild(badge);
63	    } else {
64	        stockElement.className = 'stock empty';
65	        stockElement.title = 'Sem cartas para distribuir';
66	        stockElement.textContent = '+';
67	    }
68	}
69	
70	function renderStats() {
71	    scoreElement.textContent = String(Math.max(0, state.score));
72	    movesElement.textContent = String(state.moves);
73	    runsElement.textContent = `${state.foundations.length}/${TOTAL_RUNS}`;
74	}
75	
76	function updateButtons() {
77	    undoBtn.disabled = state.undoStack.length === 0 || !state.active;
78	    hintBtn.disabled = !state.active || state.hintUsed;
79	    assistBtn.disabled = !state.active || state.assistUsed;
80	}
81	
82	function renderAll() {
83	    renderTableau();
84	    renderFoundations();
85	    renderStock();
86	    renderStats();
87	    updateButtons();
88	}
