}

function renderTableau() {
    tableauElement.innerHTML = '';
    state.columns.forEach((col, ci) => {
        const colEl = document.createElement('div');
        colEl.className = 'col' + (col.length === 0 ? ' empty' : '');
        colEl.dataset.col = String(ci);
        let top = 0;
        col.forEach((card, idx) => {
            const cardEl = document.createElement('div');
            cardEl.className = 'card ' + (card.faceUp ? 'face-up' : 'face-down');
            cardEl.dataset.col = String(ci);
            cardEl.dataset.idx = String(idx);
            cardEl.style.top = `calc(var(--card-h) * ${top.toFixed(3)})`;
            cardEl.innerHTML = card.faceUp ? cardSVG(card) : cardBackSVG();
            if (state.hint && state.hint.from === ci && state.hint.idx === idx) cardEl.classList.add('hint-src');
            if (state.grabbed && state.grabbed.col === ci && idx >= state.grabbed.idx) cardEl.classList.add('grabbed');
            if (state.cursorActive && state.cursor.col === ci && state.cursor.row === idx) cardEl.classList.add('cursor');
            colEl.appendChild(cardEl);
            top += cardStep(card);
        });
        colEl.style.height = `calc(var(--card-h) * ${(top + 1).toFixed(3)})`;
        if (state.hint && state.hint.to === ci) colEl.classList.add('hint-dst');
        tableauElement.appendChild(colEl);
    });
}

function renderFoundations() {
    foundationsElement.innerHTML = '';
    for (let i = 0; i < TOTAL_RUNS; i++) {
        const slot = document.createElement('div');
        if (state.foundations[i]) {
            slot.className = 'found-slot filled';
            slot.innerHTML = foundationSVG(state.foundations[i].suit);
        } else {
            slot.className = 'found-slot';
            slot.textContent = '?';
        }
        foundationsElement.appendChild(slot);
    }
}

function renderStock() {
    stockElement.innerHTML = '';
    const deals = Math.ceil(state.stock.length / 10);
    if (deals > 0) {
        stockElement.className = 'stock';
        stockElement.title = 'Distribuir cartas (D)';
        for (let i = 0; i < 2; i++) {
            const back = document.createElement('div');
            back.className = 'stack-card';
            back.innerHTML = cardBackSVG();
            stockElement.appendChild(back);
        }
        const badge = document.createElement('span');
        badge.className = 'badge';
        badge.textContent = String(deals);
        stockElement.appendChild(badge);
    } else {
        stockElement.className = 'stock empty';
        stockElement.title = 'Sem cartas para distribuir';
        stockElement.textContent = '+';
    }
}

function renderStats() {
    scoreElement.textContent = String(Math.max(0, state.score));
    movesElement.textContent = String(state.moves);
    runsElement.textContent = `${state.foundations.length}/${TOTAL_RUNS}`;
}

function updateButtons() {
    undoBtn.disabled = state.undoStack.length === 0 || !state.active;
    hintBtn.disabled = !state.active || state.hintUsed;
    assistBtn.disabled = !state.active || state.assistUsed;
}

function renderAll() {
    renderTableau();
    renderFoundations();
    renderStock();
    renderStats();
    updateButtons();
}

