// ===== Expressões do Espadão =====
const face = document.getElementById('face');
const eyeL = document.getElementById('eyeL');
const eyeR = document.getElementById('eyeR');
const browL = document.getElementById('browL');
const browR = document.getElementById('browR');
const mouth = document.getElementById('mouth');
let blinkScheduled = false;
let lookTimer = null;
let talkTimeout = null;

const MOUTHS = {
    happy:   'M101 96 Q110 105 119 96',
    neutral: 'M102 98 Q110 99.5 118 98',
    worried: 'M102 99 Q110 96.5 118 99',
    scared:  'M106 94 Q110 107 114 94',
    dead:    'M102 99 Q110 96 118 99'
};

const BROWS = {
    relaxed: { l: 'M93 72 Q100 68 107 72', r: 'M113 72 Q120 68 127 72' },
    tired:   { l: 'M93 73 Q100 71.5 107 72.5', r: 'M113 72.5 Q120 71.5 127 73' },
    worried: { l: 'M93 73.5 Q100 71 107 73', r: 'M113 73 Q120 71 127 73.5' },
    scared:  { l: 'M93 70.5 Q100 72 107 70.5', r: 'M113 70.5 Q120 72 127 70.5' }
};

function setBrows(expr) {
    if (!BROWS[expr]) return;
    browL.setAttribute('d', BROWS[expr].l);
    browR.setAttribute('d', BROWS[expr].r);
}

function updateFace() {
    if (!face) return;
    face.classList.remove('win', 'fear', 'dead', 'tired');

    if (!state.active && state.result !== 'win' && state.result !== 'stuck') {
        face.classList.remove('visible');
        return;
    }
    face.classList.add('visible');

    if (state.result === 'win') {
        setBrows('relaxed');
        mouth.setAttribute('d', MOUTHS.happy);
        face.classList.add('win');
        return;
    }

    if (state.result === 'stuck' || (state.active && !hasAnyMove())) {
        setBrows('scared');
        mouth.setAttribute('d', MOUTHS.scared);
        face.classList.add('fear');
        return;
    }

    const progress = state.foundations.length / TOTAL_RUNS;
    if (progress >= 0.6) {
        setBrows('tired');
        mouth.setAttribute('d', MOUTHS.neutral);
        face.classList.add('tired');
    } else if (progress >= 0.25) {
        setBrows('worried');
        mouth.setAttribute('d', MOUTHS.worried);
    } else {
        setBrows('relaxed');
        mouth.setAttribute('d', MOUTHS.happy);
    }
}

function talkFace() {
    if (!face) return;
    face.classList.add('talking');
    clearTimeout(talkTimeout);
    talkTimeout = setTimeout(() => face.classList.remove('talking'), 1600);
}

function resetFace() {
    if (!face) return;
    face.classList.remove('visible', 'dead', 'fear', 'win', 'tired', 'talking');
    setBrows('relaxed');
    mouth.setAttribute('d', MOUTHS.happy);
    [eyeL, eyeR].forEach(eye => {
        const pupil = eye.querySelector('.pupil');
        if (pupil) pupil.style.transform = '';
        eye.classList.remove('blink');
    });
}

// Piscadas periódicas
function startBlinking() {
    if (blinkScheduled) return;
    blinkScheduled = true;
    const schedule = () => {
        setTimeout(() => {
            if (face && !face.classList.contains('dead')) {
                eyeL.classList.add('blink');
                eyeR.classList.add('blink');
                setTimeout(() => {
                    eyeL.classList.remove('blink');
                    eyeR.classList.remove('blink');
                }, 130);
            }
            schedule();
        }, 1800 + Math.random() * 3400);
    };
    schedule();
}

// Pupila segue o mouse
function startEyeFollowing() {
    if (lookTimer) return;
    lookTimer = document.addEventListener('mousemove', (e) => {
        if (!face || face.classList.contains('dead') || !face.classList.contains('visible')) return;
        [eyeL, eyeR].forEach(eye => {
            const pupil = eye.querySelector('.pupil');
            if (!pupil) return;
            const rect = eye.getBoundingClientRect();
            if (!rect || rect.width === 0) return;
            const dx = e.clientX - (rect.left + rect.width / 2);
            const dy = e.clientY - (rect.top + rect.height / 2);
            const dist = Math.hypot(dx, dy);
            if (dist < 220) {
                const max = 2.6;
                const t = dist / 220;
                pupil.style.transform = `translate(${(dx / dist) * max * t}px, ${(dy / dist) * max * t}px)`;
            } else {
                pupil.style.transform = '';
            }
        });
    });
}

