// ===== Áudio (Web Audio API) =====
let audioCtx = null;

function ensureAudio() {
    if (!audioCtx) {
        try {
            audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        } catch (e) {
            audioCtx = null;
        }
    }
    if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}

function rampDown(param, toValue, when) {
    if (!param) return;
    if (toValue > 0 && typeof param.exponentialRampToTimeAtTime === 'function') {
        param.exponentialRampToTimeAtTime(toValue, when);
    } else if (toValue > 0 && typeof param.exponentialRampToValueAtTime === 'function') {
        param.exponentialRampToValueAtTime(toValue, when);
    } else if (typeof param.linearRampToValueAtTime === 'function') {
        param.linearRampToValueAtTime(0.0001, when);
    }
}

function tone(freq, duration, delay, type = 'sine', gainValue = 0.12) {
    if (!state.soundOn || !audioCtx) return;
    try {
        const start = audioCtx.currentTime + delay;
        const osc = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();
        osc.type = type;
        osc.frequency.value = freq;
        const param = gainNode.gain;
        if (param && typeof param.setValueAtTime === 'function') {
            param.setValueAtTime(gainValue, start);
            rampDown(param, 0.001, start + duration);
        }
        osc.connect(gainNode).connect(audioCtx.destination);
        osc.start(start);
        osc.stop(start + duration);
    } catch (e) {
        // áudio é opcional e nunca deve quebrar o jogo
    }
}

function playMove() { ensureAudio(); tone(340, 0.07, 0, 'triangle', 0.1); tone(260, 0.09, 0.05, 'triangle', 0.08); }
function playDeal() { ensureAudio(); [420, 520, 640].forEach((f, i) => tone(f, 0.09, i * 0.07, 'triangle', 0.1)); }
function playRun() { ensureAudio(); [660, 880, 1100, 1320].forEach((f, i) => tone(f, 0.16, i * 0.09, 'triangle', 0.13)); }
function playWin() { ensureAudio(); [523, 659, 784, 1047, 1319].forEach((f, i) => tone(f, 0.24, i * 0.13, 'triangle', 0.14)); }
function playError() { ensureAudio(); tone(150, 0.2, 0, 'square', 0.06); }

