/* Paciência Spider — estilos específicos + visual Windows XP (o design system vem do hangman.css) */
.container {
    max-width: 1380px;
}

:root {
    --card-w: clamp(44px, 8.4vw, 84px);
    --card-h: calc(var(--card-w) * 1.4);
    --felt-light: radial-gradient(ellipse at 50% 18%, #46a866 0%, #2f8f4e 55%, #226f3c 100%);
    --felt-dark: radial-gradient(ellipse at 50% 18%, #235c37 0%, #1a4a2b 55%, #123721 100%);
    --xp-blue-1: #2a5ecb;
    --xp-bar-1: #f7f9fd;
    --xp-bar-2: #e6ecf7;
    --card-black: #232338;
    --highlight: #ffd54f;
}

[data-theme="dark"] {
    --highlight: #ffe082;
}

/* ---------- Janela XP ---------- */
.xp-window {
    border: 1px solid #274b9a;
    border-radius: 10px;
    overflow: hidden;
    background: var(--xp-bar-1);
    box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
}

.xp-titlebar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 6px 10px;
    background: linear-gradient(180deg, #5b8ce8 0%, var(--xp-blue-1) 60%, #1e4bb0 100%);
    color: #fff;
    font-weight: bold;
    letter-spacing: .5px;
    text-shadow: 1px 1px 2px rgba(0, 0, 0, .35);
    user-select: none;
}

.xp-titlebtns {
    display: flex;
    gap: 3px;
}

.xp-titlebtns button {
    width: 26px;
    height: 21px;
    margin: 0;
    padding: 0;
    border: 1px solid #16366f;
    border-radius: 4px;
    background: linear-gradient(180deg, #a9c2f2, #5d87dd);
    color: #fff;
    font-size: 11px;
    line-height: 1;
    cursor: default;
}

.xp-menus {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    padding: 5px 10px;
    background: linear-gradient(180deg, var(--xp-bar-1), var(--xp-bar-2));
    border-bottom: 1px solid #c3ccda;
    user-select: none;
}

.xp-menu {
    padding: 3px 8px;
    font-size: .9em;
    color: #2c3e66;
}

.xp-menu-btn {
    padding: 4px 12px;
    font-size: .85em;
    border: 1px solid transparent;
    border-radius: 5px;
    background: transparent;
    color: #1c2c50;
    cursor: pointer;
    transition: all .15s ease;
}

.xp-menu-btn:hover:not(:disabled) {
    background: #dfe8fa;
    border-color: #9db9ef;
}

.xp-menu-btn:disabled {
    opacity: .45;
    cursor: default;
}

/* ---------- Mesa de feltro ---------- */
.felt {
    margin: 10px;
    padding: 12px;
    border-radius: 8px;
    background: var(--felt-light);
    box-shadow: inset 0 3px 12px rgba(0, 0, 0, .4);
}

[data-theme="dark"] .felt {
    background: var(--felt-dark);
}

.felt-top {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 12px;
}

.foundations {
    display: flex;
    gap: 6px;
}

.found-slot {
    width: calc(var(--card-w) * .6);
    height: calc(var(--card-w) * .6 * 1.4);
    border: 2px dashed rgba(255, 255, 255, .4);
    border-radius: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(255, 255, 255, .55);
    font-size: .95em;
    font-weight: bold;
}

.found-slot.filled {
    border: 2px solid rgba(0, 0, 0, .3);
    background: #fff;
    overflow: hidden;
    animation: runPop .5s ease;
}

.found-slot.filled svg {
    width: 100%;
    height: 100%;
    display: block;
}

@keyframes runPop {
    0%   { transform: scale(.3); }
    60%  { transform: scale(1.15); }
    100% { transform: scale(1); }
}

.stock {
    position: relative;
    flex: none;
    width: calc(var(--card-w) * .78);
    height: calc(var(--card-w) * .78 * 1.4);
    cursor: pointer;
}

.stock .stack-card {
    position: absolute;
    inset: 0;
    border-radius: 6px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, .45);
}

.stock .stack-card svg {
    width: 100%;
    height: 100%;
    display: block;
    border-radius: 6px;
}

.stock .stack-card:nth-child(1) { transform: translate(-7px, -7px); }
.stock .stack-card:nth-child(2) { transform: translate(-3.5px, -3.5px); }

.stock .badge {
    position: absolute;
    top: -10px;
    right: -8px;
    background: var(--accent);
    color: #fff;
    font-size: .78em;
    font-weight: bold;
    padding: 2px 9px;
    border-radius: 11px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, .35);
}

.stock.empty {
    cursor: default;
    border: 2px dashed rgba(255, 255, 255, .4);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(255, 255, 255, .6);
    font-size: 1.2em;
}

/* ---------- Colunas e cartas ---------- */
.tableau {
    display: grid;
    grid-template-columns: repeat(10, 1fr);
    gap: clamp(4px, .7vw, 9px);
}

.col {
    position: relative;
    isolation: isolate;
    border-radius: 8px;
}

.col.empty {
    border: 2px dashed rgba(255, 255, 255, .3);
}

.card {
    position: absolute;
    left: 0;
    width: 100%;
    height: var(--card-h);
    border-radius: 7px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, .35);
    cursor: grab;
    user-select: none;
}

.card svg {
    width: 100%;
    height: 100%;
    display: block;
}

.card.dragging {
    visibility: hidden;
}

.card.grabbed {
    box-shadow: 0 0 0 3px #40c4ff, 0 4px 10px rgba(0, 0, 0, .45);
    z-index: 25;
}

.card.cursor {
    box-shadow: 0 0 0 3px #40c4ff;
    z-index: 20;
}

.card.hint-src {
    box-shadow: 0 0 0 3px var(--highlight), 0 2px 8px rgba(0, 0, 0, .5);
    z-index: 30;
}

.col.drop-target,
.col.hint-dst {
    outline: 3px solid var(--highlight);
    outline-offset: 1px;
}

.col.hint-dst {
    outline-style: dashed;
}

/* Fantasma do arrasto */
.drag-ghost {
    position: fixed;
    z-index: 2000;
    width: var(--card-w);
    height: var(--card-h);
    pointer-events: none;
    border-radius: 7px;
    box-shadow: 0 12px 28px rgba(0, 0, 0, .55);
}

.drag-ghost svg {
    width: 100%;
    height: 100%;
    display: block;
}

/* ---------- Personagem (as de paus) ---------- */
#spadeSvg {
    width: 100%;
    max-width: 220px;
    height: auto;
    display: block;
}

.spade-body {
    fill: var(--card-black);
}

#spadeSvg .pupil {
    fill: var(--card-black);
}

#spadeSvg #sweat {
    transform-origin: 139px 70px;
}

#spadeSvg #face.talking #mouth {
    animation: spiderTalking .28s ease-in-out infinite alternate;
}

@keyframes spiderTalking {
    from { d: path("M101 96 Q110 102 119 96"); }
    to   { d: path("M101 97 Q110 108 119 97"); }
}

.mascot-caption {
    margin-top: 8px;
    text-align: center;
    font-size: .9em;
    font-style: italic;
    color: var(--text-soft);
}

/* ---------- Ajuda de teclado ---------- */
.keys-help {
    text-align: center;
    font-size: .8em;
    color: var(--text-soft);
}

/* ---------- Fogos (canvas) ---------- */
#spiderCanvas {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 1000;
    display: none;
}

